        log(
          'use-failed',
          'Both registered implementation and individual learning are required.',
          a.skillId,
        );
        continue;
      }
      try {
        const effect = executeCoevolution(world, actor, mechanic, a.args);
        effects.set(actor.id, effect);
        log('used', effect.detail, skill.id);
      } catch (error) {
        log(
          'use-failed',
