  if (Array.isArray(value)) return `[${value.map(v7Signature).join(',')}]`;
  return `{${Object.entries(value)
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
    .map(([k, v]) => `${JSON.stringify(k)}:${v7Signature(v)}`)
