export function v7CanonicalNumbers<T>(value: T): T {
  return JSON.parse(
    JSON.stringify(value, (_key: string, child: unknown) =>
      typeof child === 'number' && !Number.isInteger(child)
        ? v7RoundNumber(child)
        : child,
    ),
  ) as T;
