      best = Infinity;
    for (const id of open) {
      const score =
        (scores.get(id) ?? Infinity) + v7Distance(position(id), goal);
      if (score < best) {
        best = score;
        current = id;
      }
    }
    if (current < 0) break;
    open.delete(current);
    closed.add(current);
    const p = position(current);
