      v7Distance(p, goal) < 1.5 &&
      v7SegmentClear(p, goal, actor.radius, obstacles, work)
    ) {
      const path = [goal, p];
      let parent = previous.get(current);
      while (parent !== undefined) {
        path.push(position(parent));
        parent = previous.get(parent);
      }
      path.reverse();
