        actor.vitals.satiety <= 0 ||
        (!continuing && (actor.vitals.energy < 2 || actor.vitals.satiety < 4))
      )
        throw new Error(
          'Observation requires adequate energy and satiety; prior spent attention is not refunded.',
        );
