        delete actor.extensionState['nature-observation@1'];
        emit(
          'nature_observed',
          `Completed a two-round observation of ${object.name}; recorded its currently visible state.`,
          {
            startTick:
              typeof prior.startTick === 'number'
                ? prior.startTick
