            endTick: world.tick,
            elapsed: 2,
            observable: v7Json({
              id: object.id,
              name: object.name,
              kind: object.kind,
              spatial: { ...object.spatial },
              data: object.data,
              state: object.visual.state,
            }),
          },
          target,
        );
        return { complete: true, writes: [] };
      }
