  forest?: {
    version: 1;
    day: number;
    year: number;
    respawnSatiety: number;
    lives: number;
  };
}
export interface V7World {
  protocol: 'continuous-v1';
  tick: number;
  time: number;
  config: V7Configuration;
  terrain: string[];
