      ...m,
      visited: [...new Set([...m.visited, cellKey(actor.position)])],
      discovered: [
        ...new Set([
          ...m.discovered,
          ...data.sites.filter((s) => visible(s.position)).map((s) => s.id),
          ...data.stacks
            .filter((s) => s.position && visible(s.position))
            .map((s) => s.id),
        ]),
      ],
    };
  }
