          const before = context.actor.vitals.satiety;
          context.actor.vitals.satiety = Math.min(
            100,
            before + n * resource.nutrition,
          );
          context.actor.vitals.health = Math.max(
            0,
            healthBefore - n * resource.toxicity,
          );
          context.emit(
            'ate',
            `Consumed ${String(n)} ${resource.name}; gained ${String(context.actor.vitals.satiety - before)} satiety.`,
