import { v7Observe } from '@self-evolving-world/world-core';
import type {
  V7World,
  V7Actor,
  V7Object,
  V7Event,
  WorldState,
} from '@self-evolving-world/world-core';
import { continuousObjectVisual, svgText } from './continuous-visuals.js';
export interface SceneFrame {
  tick: number;
  width: number;
