import {
  biomeAt,
  isVisible,
  carryingLoad,
} from '@self-evolving-world/world-core';
import type {
  AgentState,
  Cell,
  WorldState,
  LearningEvent,
  CoevolutionEvent,
} from '@self-evolving-world/world-core';
import type { Timeline } from './timeline.js';
import { itemIllustration } from './illustrations.js';
function el(id: string): HTMLElement {
  const node = document.getElementById(id);
  if (!node) throw Error(`Missing ${id}.`);
  return node;
}
function text(tag: string, value: string, className = '') {
  const node = document.createElement(tag);
  node.textContent = value;
  node.className = className;
  return node;
}
export function evolutionIcon(appearance: string): string {
  return /cap|mushroom|fung/i.test(appearance)
    ? 'mushroom'
    : /branch|wood|reed|rod/i.test(appearance)
      ? 'wood'
      : /rock|stone/i.test(appearance)
        ? 'stone'
        : /berry|fruit/i.test(appearance)
          ? 'berry'
          : /fish|water/i.test(appearance)
            ? 'water'
            : 'seed';
}
export function decorateEvolutionCell(
  cell: HTMLElement,
  frame: WorldState,
  p: Cell,
): void {
  const data = frame.coevolution ?? frame.evolution;
  if (!data) return;
  const biome = biomeAt(data, p);
  cell.classList.add(`biome-${biome}`);
  cell.dataset.terrain = biome;
  cell.title = `${biome} (${String(p.x)}, ${String(p.y)})${biome === 'river' ? ' · Impassable' : biome === 'shallow' ? ' · Passable crossing' : ''}`;
  const site = data.sites.find(
    (s) => s.position.x === p.x && s.position.y === p.y,
  );
  for (const object of frame.coevolution?.objects.filter(
    (o) => o.position?.x === p.x && o.position.y === p.y,
  ) ?? []) {
    const token = text('span', '◇', 'environment-token persistent-object');
    token.dataset.persistentObject = object.id;
    token.title = `${object.id} · ${frame.coevolution?.blueprints.find((b) => b.id === object.blueprint)?.name ?? object.blueprint}`;
    token.setAttribute('aria-label', token.title);
    cell.append(token);
  }
  if (site) {
    const token = text('span', '', `environment-token site-${site.kind}`);
    token.dataset.mapObject = site.id;
    token.title = `${site.id} · ${site.appearance}`;
    token.setAttribute('aria-label', token.title);
    if (site.kind === 'tree')
      token.innerHTML =
        '<svg viewBox="0 0 32 32" aria-hidden="true"><path fill="#c1a477" d="M14 15h5v17h-5z"/><path fill="#a0bf83" d="M16 0 3 21h26z"/><path fill="#6d9c71" d="m16 7-13 21h26z"/></svg>';
    else
      token.append(
        itemIllustration(
          site.kind === 'rock'
            ? 'stone'
            : site.kind === 'fungus'
              ? 'mushroom'
              : 'water',
        ),
      );
    cell.append(token);
  }
}
export function evolutionEventText(frame: WorldState): string {
  return (
    (frame.coevolution ?? frame.evolution)?.events
      .map(
        (e) =>
          `${frame.agents.find((a) => a.id === e.action.agentId)?.name ?? e.action.agentId} · ${e.action.type} · ${e.outcome}: ${e.detail}`,
      )
      .join('\n') ||
    (frame.coevolution
      ? 'Development world created. Basic eating and initial safe foods are authored knowledge.'
      : 'Heterogeneous world created. Resource safety is unknown until personally learned.')
  );
}
export function renderEvolutionPanel(
  frame: WorldState,
  actor: AgentState,
  timeline: Timeline,
  cursor: number,
): void {
  const data = frame.coevolution ?? frame.evolution;
  if (!data) return;
  el('survival-environment').textContent = frame.coevolution
    ? 'Primitive era · Health100 / satiety80 initially · Prelearned eating · Carrying uses energy; rest restores4 plus actual object effects.'
    : 'Primitive era · At zero satiety: −10 health, then −2 satiety. Initial satiety 60. Deep river blocks movement; shallows connect regions.';
  el('learning-policy').textContent = frame.coevolution
    ? 'Versioned, costed world changes · Individual learning · Finite ecology and delayed shared outputs.'
    : 'World review and development complete at the round barrier. Shared implementations require individual learning; no resource replenishment.';
  const programs =
      (timeline.coevolutionPrograms ?? timeline.evolutionPrograms)?.filter(
        (p) => p.agentId === actor.id && p.tick <= frame.tick,
      ) ?? [],
    active = programs.at(-1);
  el('program-status').textContent =
    `${String(programs.length)} actor calls${frame.coevolution ? ' · 120 shared ordinary attempts maximum' : ' / 60 maximum'} · Up to 12 rounds per plan · ${frame.coevolution ? 'Failure, danger or invalid targets can interrupt' : 'Failure, danger or encounters can interrupt'}`;
  el('program-code').textContent =
    active?.code ?? 'No accepted program; wait fallback.';
  el('program-summary').textContent =
    active?.summary ?? 'No decision recorded at this frame.';
  const feedback = timeline.frames
    .slice(1, cursor + 1)
    .flatMap<LearningEvent | CoevolutionEvent>(
      (f) => (f.coevolution ?? f.evolution)?.events ?? [],
    )
    .filter(
      (e) =>
        e.action.agentId === actor.id &&
        ['learn', 'study', 'use'].includes(e.action.type),
    );
  el('learning-history').replaceChildren(
    ...(feedback.length
      ? feedback
          .slice(-8)
          .map((e) =>
            text(
              'p',
              `Round ${String(e.tick)} · ${e.outcome} · ${e.detail}`,
              'learning-record',
            ),
          )
      : [text('p', 'No requests yet.', 'muted')]),
  );
  const knowledge = data.knowledge[actor.id],
    memory = data.memory[actor.id];
  el('world-skill-count').textContent =
    `${String(data.skills.length)} world implementations · ${String(data.types.length)} resource types · ${String(data.ecology.length)} ecological rules`;
  el('learning-progress').textContent = knowledge?.pending
    ? `Learning ${knowledge.pending.skillId}: ${String(knowledge.pending.completed)} / ${String(knowledge.pending.total)} rounds completed`
    : 'No learning in progress.';
  const skills = data.skills.filter((s) => knowledge?.learned.includes(s.id));
  el('learned-skills').replaceChildren(
    ...(skills.length
      ? skills.map((s) => {
          const m = data.mechanics.find((m) => m.id === s.mechanicId),
            d = document.createElement('details');
          d.className = 'learned-skill';
          d.dataset.learnedSkill = s.id;
          d.append(
            text(
              'summary',
              `${s.name} · ${s.id} v${String(s.version)} · Learned`,
            ),
            text('p', s.description),
            text('p', `Parameters: ${m?.parameters.join(', ') ?? ''}`),
            text('pre', m?.code ?? '', 'program-code'),
          );
          return d;
        })
      : [text('p', 'No learned extension skills.', 'muted')]),
  );
  const rows = data.stacks
    .filter(
      (s) =>
        s.quantity > 0 &&
        (s.owner === actor.id ||
          (s.position &&
            isVisible(
              actor.position,
              s.position,
              frame.settings.visionRadius,
            ))),
    )
    .map((s) => {
      const type = data.types.find((t) => t.id === s.type),
        known = memory?.knownTypes.includes(s.type);
      return text(
        'p',
        `${s.id} · ${s.owner === actor.id ? 'Carried' : 'Ground'} · ${String(s.quantity)} units · ${type?.appearance ?? s.type} · ${known ? `nutrition ${String(type?.nutrition)}, toxicity ${String(type?.toxicity)}` : 'Properties unknown'}${s.durability ? ` · durability ${String(s.durability)}` : ''}`,
        'resource-detail',
      );
    });
  for (const site of data.sites.filter((s) =>
    isVisible(actor.position, s.position, frame.settings.visionRadius),
  ))
    rows.push(
      text(
        'p',
        `${site.id} · ${site.appearance} · ${
          memory?.inspected.includes(site.id)
            ? `Observed stock: ${
                Object.entries(site.stock)
                  .map(([k, n]) => `${k} ${String(n)}`)
                  .join(', ') || 'empty'
              }`
            : 'Contents unexamined'
        }`,
        'resource-detail',
      ),
    );
  rows.unshift(
    text(
      'p',
      `Personal experience: ${String(memory?.visited.length ?? 0)} visited cells · ${String(memory?.discovered.length ?? 0)} discovered objects · ${String(memory?.knownTypes.length ?? 0)} identified types`,
      'resource-detail',
    ),
  );
  if (frame.coevolution) {
    const c = frame.coevolution,
      project = timeline.coevolutionPrograms
        ?.filter(
          (p) => p.agentId === actor.id && p.tick <= frame.tick && p.project,
        )
        .at(-1)?.project;
    rows.unshift(
      text(
        'p',
        `Energy: ${String(c.energy[actor.id])} / 40 · Carried load: ${String(carryingLoad(c, actor.id))} units`,
        'resource-detail',
      ),
    );
    if (project)
      rows.unshift(
        text(
          'p',
          `Project: ${project.problem} · Why: ${project.reason} · Progress: ${project.progress} · Missing: ${project.missing} · Observed: ${project.observedEffects}`,
          'resource-detail',
        ),
      );
    for (const o of c.objects.filter(
      (o) =>
        o.owner === actor.id ||
        (o.position &&
          isVisible(actor.position, o.position, frame.settings.visionRadius)),
    )) {
      const b = c.blueprints.find((b) => b.id === o.blueprint);
      rows.push(
        text(
          'p',
          `${o.id} · ${b?.name ?? o.blueprint} · Creator ${o.creator} · ${o.owner ? `Carried by ${o.owner}` : 'Shared stationary object'} · Rest +${String(b?.restBonus)} · Carry aid ${String(b?.carryBonus)}${o.growth && b?.growth ? ` · Produced ${String(o.growth.produced)}/${String(b.growth.lifetime)} ${b.growth.output} · ${o.growth.produced >= b.growth.lifetime ? 'Lifetime production exhausted' : `Next maturity check ${String(o.growth.next)}`} · Environmental nutrition ${String(o.growth.environmentalEnergy)}` : ''}`,
          'resource-detail',
        ),
      );
    }
    for (const m of c.messages
      .filter((m) => m.recipient === actor.id)
      .slice(-4))
      rows.push(
        text(
          'p',
          `Message from ${m.sender} at round ${String(m.tick)}: ${m.text}`,
          'resource-detail',
        ),
      );
  }
  el('resource-details').replaceChildren(...rows);
}

apps/viewer/src/experiments.ts:
import { MAX_ACTIONS, MAX_REPLAY_BYTES, parseReplay } from './timeline.js';
import type { Timeline } from './timeline.js';

export interface ExperimentEntry {
  readonly id: string;
  readonly objective: string;
  readonly steps: number;
  readonly seed?: number;
  readonly createdAt: string;
  readonly schedule?:
    | 'simultaneous-v1'
    | 'survival-v1'
    | 'learning-v1'
    | 'evolution-v1'
    | 'coevolution-v1'
    | 'continuous-v1';
  readonly totalActions?: number;
}

function object(value: unknown): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value))
    throw new Error('Invalid experiment catalogue.');
  return value as Record<string, unknown>;
}

export function parseCatalogue(source: string): ExperimentEntry[] {
  if (new TextEncoder().encode(source).length > MAX_REPLAY_BYTES)
    throw new Error('Experiment catalogue is too large.');
  const value = object(JSON.parse(source) as unknown);
  if (value.version !== 1 || !Array.isArray(value.experiments))
    throw new Error('Unsupported experiment catalogue.');
  const ids = new Set<string>();
  return value.experiments.map((item: unknown) => {
    const { id, objective, steps, seed, createdAt, schedule, totalActions } =
      object(item);
    if (
      (schedule !== undefined &&
        schedule !== 'simultaneous-v1' &&
        schedule !== 'survival-v1' &&
        schedule !== 'learning-v1' &&
        schedule !== 'evolution-v1' &&
        schedule !== 'coevolution-v1' &&
        schedule !== 'continuous-v1') ||
      (schedule !== undefined &&
        (typeof totalActions !== 'number' ||
          !Number.isInteger(totalActions) ||
          typeof steps !== 'number' ||
          totalActions < steps ||
          totalActions > steps * 32)) ||
      typeof id !== 'string' ||
      !/^ex[1-9]\d*$/.test(id) ||
      !Number.isSafeInteger(Number(id.slice(2))) ||
      ids.has(id) ||
      typeof objective !== 'string' ||
      objective.trim().length < 20 ||
      objective.length > 1000 ||
      typeof steps !== 'number' ||
      !Number.isInteger(steps) ||
      steps <
        (schedule === 'coevolution-v1' || schedule === 'continuous-v1'
          ? 0
          : 3) ||
      (schedule !== 'continuous-v1' && steps > MAX_ACTIONS) ||
      (schedule === 'survival-v1' ||
      schedule === 'learning-v1' ||
      schedule === 'evolution-v1' ||
      schedule === 'coevolution-v1' ||
      schedule === 'continuous-v1'
        ? seed !== undefined
        : typeof seed !== 'number' ||
          !Number.isInteger(seed) ||
          seed < 1 ||
          seed > 0xffffffff) ||
      typeof createdAt !== 'string' ||
      !Number.isFinite(Date.parse(createdAt))
    )
      throw new Error('Invalid or duplicate experiment entry.');
    ids.add(id);
    return {
      id,
      objective,
      steps,
      ...(typeof seed === 'number' ? { seed } : {}),
      createdAt,
      ...((schedule === 'simultaneous-v1' ||
        schedule === 'survival-v1' ||
        schedule === 'learning-v1' ||
        schedule === 'evolution-v1' ||
        schedule === 'coevolution-v1' ||
        schedule === 'continuous-v1') &&
      typeof totalActions === 'number'
        ? { schedule, totalActions }
        : {}),
    };
  });
}

async function readAsset(path: string): Promise<string> {
  const response = await fetch(`./experiments/${path}`, { cache: 'no-store' });
  if (!response.ok)
    throw new Error(`Archive request failed (${String(response.status)}).`);
  return response.text();
}

function find<K extends keyof HTMLElementTagNameMap>(
  id: string,
  tag: K,
): HTMLElementTagNameMap[K] {
  const element = document.querySelector(`${tag}#${id}`);
  if (element === null) throw new Error(`Missing experiment control: ${id}`);
  return element as HTMLElementTagNameMap[K];
}

/** Selection commits only after validation. Sequence tokens discard obsolete requests. */
export class ExperimentBrowser {
  private readonly select = find('experiment-select', 'select');
  private readonly details = find('experiment-details', 'p');
  private readonly feedback = find('experiment-feedback', 'p');
  private readonly chart = find('experiment-chart', 'a');
  private entries: ExperimentEntry[] = [];
  private active: ExperimentEntry | undefined;
  private sequence = 0;

  constructor(
    private readonly load: (
      timeline: Timeline | undefined,
      id: string | undefined,
    ) => void,
    private readonly loading: (pending: boolean) => void,
  ) {
    this.select.addEventListener('change', () => {
      void this.open(this.select.value, true);
    });
    window.addEventListener('popstate', () => {
      void this.open(this.requestedId(), false);
    });
  }

  private requestedId(): string {
    return new URL(window.location.href).searchParams.get('experiment') ?? '';
  }

  private updateUrl(id: string, push: boolean): void {
    const url = new URL(window.location.href);
    if (id === '') url.searchParams.delete('experiment');
    else url.searchParams.set('experiment', id);
    if (url.href !== window.location.href) {
      if (push) window.history.pushState(null, '', url);
      else window.history.replaceState(null, '', url);
    }
  }

  private showActive(): void {
    this.select.value = this.active?.id ?? '';
    this.details.textContent =
      this.active?.objective ??
      'Choose a saved experiment to explore its full history.';
    this.chart.hidden = this.active === undefined;
    if (this.active !== undefined) {
      this.chart.href = `./experiments/${this.active.id}/overview.svg`;
      this.feedback.textContent = `${this.active.id} · ${String(this.active.steps + 1)} frames${this.active.schedule ? ` · ${String(this.active.totalActions)} actions` : ''} · ${this.active.schedule === 'coevolution-v1' ? 'Development and coevolution · 180 target rounds · 120 shared ordinary attempts' : this.active.schedule === 'evolution-v1' ? 'World evolution · 60 calls per actor maximum' : this.active.schedule === 'learning-v1' ? 'Survival-driven skills · 12 calls per actor maximum' : this.active.schedule === 'survival-v1' ? 'ChatGPT programs · 5 calls per actor maximum' : `Seed ${String(this.active.seed)}`} · Read-only archive`;
    } else {
      this.chart.removeAttribute('href');
      this.feedback.textContent =
        this.entries.length === 0
          ? 'No completed experiments available. The demo is ready to explore.'
          : `${String(this.entries.length)} saved experiment${this.entries.length === 1 ? '' : 's'} · Local session`;
    }
  }

  /** Called before replacing the world with a local demo, new world or valid import. */
  public localSession(): void {
    this.sequence += 1;
    this.active = undefined;
    this.loading(false);
    this.updateUrl('', true);
    this.showActive();
  }

  public async start(): Promise<void> {
    const sequence = this.sequence;
    if (this.requestedId() !== '') this.loading(true);
    try {
      this.entries = parseCatalogue(await readAsset('index.json'));
      for (const entry of this.entries) {
        const option = document.createElement('option');
        option.value = entry.id;
        option.textContent = `${entry.id} · ${String(entry.steps)} ${entry.schedule ? 'rounds' : 'steps'}`;
        this.select.append(option);
      }
      this.select.disabled = false;
      this.showActive();
      if (sequence === this.sequence && this.requestedId() !== '')
        await this.open(this.requestedId(), false);
    } catch {
      if (sequence === this.sequence) this.loading(false);
      this.feedback.textContent =
        'Experiment catalogue could not be loaded. Refresh to retry; your current history is unchanged.';
    }
  }

  private async open(id: string, push: boolean): Promise<void> {
    const sequence = ++this.sequence;
    if (id === '') {
      this.active = undefined;
      this.loading(false);
      this.load(undefined, undefined);
      this.updateUrl('', push);
      this.showActive();
      return;
    }
    this.loading(true);
    this.feedback.textContent = `Loading ${id}…`;
    try {
      const entry = this.entries.find((candidate) => candidate.id === id);
      if (entry === undefined)
        throw new Error('This experiment is not in the completed archive.');
      if (entry.schedule === 'continuous-v1') {
        window.location.assign(
          `./observatory.html?experiment=${encodeURIComponent(entry.id)}`,
        );
        return;
      }
      const timeline = parseReplay(await readAsset(`${entry.id}/replay.json`));
      if (
        timeline.frames.length !== entry.steps + 1 ||
        timeline.schedule !== entry.schedule ||
        (entry.schedule &&
          timeline.frames
            .slice(1)
            .reduce(
              (count, frame) =>
                count +
                ((frame.coevolution ?? frame.evolution)?.events.length ??
                  frame.learning?.events.length ??
                  frame.survival?.events.length ??
                  frame.events?.length ??
                  0),
              0,
            ) !== entry.totalActions)
      )
        throw new Error(
          'Replay length disagrees with the experiment catalogue.',
        );
      if (sequence !== this.sequence) return;
      this.active = entry;
      this.loading(false);
      this.load(timeline, id);
      this.updateUrl(id, push);
      this.showActive();
    } catch (error) {
      if (sequence !== this.sequence) return;
      this.loading(false);
      this.updateUrl(this.active?.id ?? '', false);
      this.showActive();
      this.feedback.textContent = `Could not load ${id}. Current history is unchanged. ${error instanceof Error ? error.message : 'Select the experiment to retry.'}`;
    }
  }
}

