  const actions: readonly WorldAction[] = [
    { type: 'move', agentId: 'lin', direction: 'east' },
    { type: 'pickup', agentId: 'lin', itemId: 'wood' },
    { type: 'try', agentId: 'lin', skill: 'fly' },
    { type: 'move', agentId: 'lin', direction: 'south' },
    { type: 'move', agentId: 'lin', direction: 'east' },
    { type: 'move', agentId: 'moss', direction: 'north' },
    { type: 'pickup', agentId: 'moss', itemId: 'berry' },
    { type: 'move', agentId: 'moss', direction: 'west' },
    { type: 'try', agentId: 'moss', skill: 'plant' },
    { type: 'move', agentId: 'sol', direction: 'west' },
    { type: 'pickup', agentId: 'sol', itemId: 'crystal' },
    { type: 'move', agentId: 'sol', direction: 'north' },
  ];
  return actions.reduce(appendAction, createTimeline(DEMO_SETUP));
}

apps/viewer/src/style.css:
:root {
  font-family:
    Inter,
    -apple-system,
    BlinkMacSystemFont,
    'Segoe UI',
    'PingFang SC',
    'Microsoft YaHei',
    sans-serif;
  color: #263f37;
  background: #f4f5ef;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  --ink: #263f37;
  --muted: #77847b;
  --line: #e5e9df;
  --green: #2d6651;
  --orange: #c57742;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
}
button,
input,
select {
  font: inherit;
}
button,
select {
  cursor: pointer;
}
button {
  color: inherit;
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.38;
}
button {
  transition:
    background 0.15s ease,
    color 0.15s ease,
    box-shadow 0.15s ease;
}
button:focus-visible,
input:focus-visible,
select:focus-visible,
a:focus-visible {
  outline: 3px solid #d9955c;
  outline-offset: 3px;
}
button:hover:not(:disabled) {
  filter: brightness(0.97);
}
h1,
h2,
h3,
p {
  margin: 0;
}
.topbar {
  height: 78px;
  border-bottom: 1px solid #e0e5db;
  display: flex;
  align-items: center;
  gap: 25px;
  padding: 0 4.3%;
  background: #fafbf6;
}
.brand {
  text-decoration: none;
  color: var(--ink);
  display: flex;
  gap: 11px;
  align-items: center;
  font-size: 11px;
  letter-spacing: 1.7px;
}
.brand b {
  font-weight: 750;
}
.brand-symbol {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  color: #faf8ed;
  background: #335a49;
  border-radius: 9px;
  font-size: 27px;
}
.edition {
  font-family: ui-monospace, monospace;
  color: #98a197;
  font-size: 10px;
  letter-spacing: 1px;
  border-left: 1px solid var(--line);
  padding-left: 25px;
}
.header-actions {
  margin-left: auto;
  display: flex;
  gap: 10px;
}
.button {
  border: 1px solid #d9e0d4;
  padding: 10px 15px;
  border-radius: 7px;
  font-size: 12px;
  background: #fcfdf9;
  font-weight: 600;
  white-space: nowrap;
}
.button.quiet {
  border-color: transparent;
  background: transparent;
  color: #66796c;
}
.workspace {
  max-width: 1460px;
  margin: auto;
  padding: 40px 4.3% 0;
}
.page-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 31px;
  gap: 20px;
}
.eyebrow {
  font-size: 9px;
  font-weight: 650;
  letter-spacing: 2px;
  color: #8a988b;
  line-height: 1.5;
}
h1 {
  font-size: 35px;
  letter-spacing: -1px;
  font-weight: 650;
  margin-top: 9px;
}
.title-dot {
  color: var(--orange);
  margin-left: 4px;
}
.subtitle {
  font-size: 12px;
  color: var(--muted);
  margin-top: 10px;
  letter-spacing: 0.5px;
}
.session-actions {
  display: flex;
  gap: 20px;
  align-items: center;
}
.rule-badge {
  color: #687e6d;
  font-size: 11px;
  letter-spacing: 0.5px;
}
.main-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 310px;
  gap: 24px;
  align-items: start;
}
.experiment-browser {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 18px 28px;
  padding: 20px 24px;
  margin-bottom: 24px;
  border: 1px solid #d9e2d2;
  border-radius: 12px;
  background: #edf1e7;
}
.experiment-picker {
  display: grid;
  gap: 8px;
  flex: 0 1 220px;
  min-width: 0;
}
#experiment-select {
  width: 100%;
  min-width: 0;
  padding: 10px 12px;
  color: var(--ink);
  border: 1px solid #c8d5c3;
  border-radius: 6px;
  background: #fdfef9;
  font-size: 13px;
}
.experiment-description {
  flex: 1 1 330px;
  min-width: 0;
  font-size: 12px;
  line-height: 1.7;
  overflow-wrap: anywhere;
}
#experiment-feedback {
  color: #61715f;
  font-size: 11px;
  margin-top: 4px;
}
#experiment-chart {
  text-decoration: none;
}
.world-column,
.inspector {
  display: grid;
  gap: 22px;
  min-width: 0;
}
.panel {
  background: #fdfef9;
  border: 1px solid #e0e6da;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 3px 8px #263f3703;
}
.panel-heading {
  padding: 22px 24px 18px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
}
h2 {
  font-size: 16px;
  font-weight: 650;
  margin-top: 5px;
}
h3 {
  font-size: 12px;
  font-weight: 650;
}
.mono {
  font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', monospace;
}
#world-size {
  font-size: 11px;
  margin-left: 10px;
  color: #9aa38f;
  font-weight: 400;
}
.view-switch {
  display: flex;
  padding: 3px;
  background: #edf0e8;
  border-radius: 6px;
  gap: 2px;
}
.view-switch button {
  border: 0;
  background: transparent;
  border-radius: 4px;
  color: #879281;
  font-size: 11px;
  padding: 7px 11px;
}
.view-switch button[aria-pressed='true'] {
  background: #fcfdf9;
  color: #304e3b;
  box-shadow: 0 1px 4px #34482d15;
}
.map-stats {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 12px 24px;
  font-size: 10px;
  color: #778672;
  border-top: 1px solid var(--line);
}
.map-stats > :last-child {
  margin-left: auto;
  font-size: 10px;
  letter-spacing: 1px;
}
.map-stats b {
  margin-left: 5px;
  color: #365445;
}
.status-dot {
  display: inline-block;
  height: 5px;
  width: 5px;
  border-radius: 50%;
  background: #7fa782;
  margin-right: 7px;
  vertical-align: 2px;
}
.map-surround {
  background: #193b32;
  padding: 15px 19px 15px 12px;
}
.x-axis {
  margin-left: 22px;
  display: grid;
  color: #719085;
  font:
    9px ui-monospace,
    monospace;
  height: 20px;
  text-align: center;
}
.map-row {
  display: flex;
}
.y-axis {
  width: 22px;
  flex-shrink: 0;
  display: grid;
  text-align: center;
  color: #719085;
  font:
    9px ui-monospace,
    monospace;
}
.y-axis span {
  align-self: center;
}
.world-grid {
  flex: 1;
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(var(--columns), minmax(0, 1fr));
  aspect-ratio: var(--columns) / var(--rows);
  border: 1px solid #496b584f;
  border-right: 0;
  border-bottom: 0;
}
.cell {
  position: relative;
  min-width: 0;
  min-height: 0;
  display: grid;
  place-items: center;
  border-right: 1px solid #65857522;
  border-bottom: 1px solid #65857522;
  background: #204639;
}
.cell:nth-child(3n) {
  background: #234a3c;
}
.cell.textured::before {
  content: '·';
  color: #44664b;
  position: absolute;
  font-size: 18px;
}
.cell.visible {
  background: #3b5b42;
  border-color: #b0bd762c;
}
.cell.visible:nth-child(3n) {
  background: #405e43;
}
.cell.fog,
.cell.fog:nth-child(3n) {
  background: #15362e;
  border-color: #6283720e;
}
.cell.fog::before {
  content: '';
}
.agent-token {
  padding: 0;
  border: 0;
  border-radius: 30%;
  width: 88%;
  aspect-ratio: 1;
  z-index: 2;
  background: transparent;
  filter: drop-shadow(0 1px 1px #0b282a90);
}
.agent-token.selected {
  outline: 1px solid #f3d997;
  outline-offset: 1px;
  background: #f5dc8c1c;
}
.agent-token svg,
.item-token svg {
  display: block;
  width: 100%;
  height: 100%;
}
.item-token {
  width: 70%;
  aspect-ratio: 1;
  position: absolute;
  filter: drop-shadow(0 1px 2px #102b3280);
}
.cell:has(.agent-token) .item-token {
  top: 0;
  right: 0;
  width: 43%;
  z-index: 3;
}
.item-count {
  position: absolute;
  right: -2px;
  bottom: 0;
  color: white;
  font-size: 9px;
}
.inventory-item {
  display: inline-flex;
  gap: 5px;
  align-items: center;
}
.inventory-item svg {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
}
#current-event,
.event-description {
  white-space: pre-line;
}
.map-caption {
  margin-left: 22px;
  padding-top: 13px;
  font-size: 9px;
  color: #8ea798;
  display: flex;
  justify-content: space-between;
  gap: 8px;
}
.map-legend {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 13px 24px;
  color: #82917c;
  font-size: 10px;
  border-bottom: 1px solid var(--line);
}
.map-legend i {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 4px;
}
.legend-agent {
  background: #d1b589;
  border-radius: 50%;
}
.legend-item {
  background: #b6b783;
  transform: rotate(45deg);
  width: 5px !important;
  height: 5px !important;
}
.legend-vision {
  border: 1px solid #a3ac83;
  background: #e2e6ce;
}
.map-tip {
  margin-left: auto;
  color: #a2aa9a;
  font-size: 9px;
}
.replay-panel {
  padding: 23px 24px 20px;
  background: #f9fbf5;
}
.replay-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.replay-title h3 {
  margin-top: 5px;
  font-size: 14px;
}
#history-count {
  font-size: 11px;
  color: #688270;
  letter-spacing: 1px;
}
#timeline {
  display: block;
  width: 100%;
  height: 4px;
  border-radius: 2px;
  appearance: none;
  background: linear-gradient(
    to right,
    #698f6e var(--progress),
    #e1e7d9 var(--progress)
  );
  margin: 25px 0 20px;
  cursor: pointer;
}
#timeline::-webkit-slider-thumb {
  appearance: none;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #547d5c;
  border: 2px solid #fafcf3;
  box-shadow: 0 0 0 1px #547d5c;
}
#timeline::-moz-range-thumb {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #547d5c;
  border: 2px solid #fafcf3;
}
.playback-controls,
.transport,
.playback-options {
  display: flex;
  align-items: center;
  gap: 7px;
}
.playback-controls {
  justify-content: space-between;
}
.icon-button {
  border: none;
  background: transparent;
  min-width: 29px;
  height: 31px;
  color: #87997d;
  font-size: 20px;
}
#first-frame {
  font-size: 12px;
}
.button.play {
  background: #335a43;
  border-color: #335a43;
  color: #fcfcf0;
  padding: 9px 20px;
  font-size: 11px;
}
#speed {
  border: 0;
  color: #71876d;
  background: transparent;
  font-size: 11px;
  padding: 6px;
}
.current-event {
  margin-top: 15px;
  padding-top: 13px;
  border-top: 1px solid #e7ecdf;
  font-size: 12px;
  color: #657a5d;
  line-height: 1.7;
}
.small-label {
  font-size: 9px;
  color: #7e947c;
  padding: 4px 6px;
  background: #edf2e8;
  border-radius: 3px;
  white-space: nowrap;
}
.agent-panel .panel-heading,
.skills-panel .panel-heading {
  padding: 22px 21px 17px;
}
.agent-select {
  display: block;
  width: calc(100% - 42px);
  margin: 0 21px;
  padding: 13px 11px;
  border: 1px solid #dce5d5;
  border-radius: 6px;
  color: #3f5b42;
  background: #f7f9f1;
  font-size: 12px;
}
.agent-meta {
  margin: 20px 21px 0;
  padding-bottom: 19px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  border-bottom: 1px solid var(--line);
}
.agent-meta span {
  font-size: 10px;
  color: #8c9a86;
  display: block;
  margin-bottom: 7px;
}
.agent-meta strong {
  font-size: 15px;
  color: #4e6851;
  font-weight: 500;
}
.inspector-block {
  margin: 20px 21px;
}
.inspector-block h3 {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #52664c;
  font-size: 11px;
}
#inventory-count {
  font-size: 10px;
  color: #8e9c81;
  font-weight: 400;
}
.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 10px;
}
.inventory-item {
  color: #827447;
  border: 1px solid #e6e0c7;
  border-radius: 4px;
  background: #f8f5e6;
  padding: 6px 10px;
  font-size: 10px;
}
.empty-note,
.muted {
  font-size: 10px;
  color: #92a08a;
  line-height: 1.9;
}
.auto-label {
  color: #a7b09a;
  font-size: 9px;
  font-weight: 400;
}
.muted {
  margin: 10px 0 6px;
}
.visible-entities {
  display: flex;
  flex-wrap: wrap;
  gap: 7px 10px;
  font-size: 11px;
  line-height: 1.6;
  color: #6e7e65;
}
.seen-agent {
  color: #688773;
}
.skills-panel {
  padding-bottom: 9px;
}
.action-hint {
  font-size: 11px;
  color: #6e7e65;
  line-height: 1.8;
  background: #f2f5eb;
  padding: 10px 13px;
  margin: 0 21px 19px;
  border-left: 2px solid #becbae;
}
fieldset {
  border: 0;
  margin: 0;
  padding: 0 21px 8px;
  min-width: 0;
}
.skill-heading {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}
.skill-number {
  font:
    9px ui-monospace,
    monospace;
  color: #9aa98b;
  border: 1px solid #e3e9d9;
  padding: 4px 5px;
  border-radius: 3px;
}
.skill-heading h3 {
  font-size: 12px;
}
.skill-heading p {
  font-size: 11px;
  margin-top: 5px;
  color: #6e7e65;
  line-height: 1.6;
}
.key-hint {
  margin-left: auto;
  flex-shrink: 0;
  white-space: nowrap;
  font:
    8px ui-monospace,
    monospace;
  color: #acb49f;
  padding-top: 5px;
}
.move-pad {
  display: grid;
  grid-template-areas: '. north .' 'west center east' '. south .';
  grid-template-columns: repeat(3, 36px);
  grid-template-rows: repeat(3, 31px);
  gap: 5px;
  justify-content: center;
  padding: 15px 0 0;
}
.move-pad button {
  background: #f2f5eb;
  border: 1px solid #dde6d3;
  border-radius: 5px;
  color: #6c8460;
  font-size: 16px;
}
.move-pad .north {
  grid-area: north;
}
.move-pad .south {
  grid-area: south;
}
.move-pad .east {
  grid-area: east;
}
.move-pad .west {
  grid-area: west;
}
.move-center {
  grid-area: center;
  display: grid;
  place-items: center;
  color: #a7b49a;
  font-size: 12px;
}
.skill-divider {
  height: 1px;
  background: var(--line);
  margin: 19px 0;
}
.empty-pickup {
  font-size: 11px;
  color: #6e7e65;
  background: #f8faf3;
  border: 1px dashed #e3e9d8;
  padding: 10px;
  border-radius: 4px;
  margin-top: 13px;
  text-align: center;
}
.pickup-button {
  font-size: 11px;
  background: #e9f0e2;
  color: #526d43;
  border: 1px solid #d4e1c9;
  width: 100%;
  margin-top: 12px;
  border-radius: 5px;
  padding: 10px;
}
.activity-panel .panel-heading {
  padding-bottom: 9px;
}
.activity-note {
  font-size: 11px;
  color: #6e7e65;
  padding: 0 24px 17px;
}
.event-row {
  width: 100%;
  border: 0;
  background: transparent;
  border-top: 1px solid #edf0e6;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  text-align: left;
  gap: 17px;
}
.event-tick {
  color: #a5b099;
  font-size: 10px;
}
.event-description {
  color: #657a5d;
  font-size: 12px;
  line-height: 1.7;
}
.event-row.unsupported .event-description {
  color: #ad8e60;
}
.event-arrow {
  margin-left: auto;
  color: #afb99f;
  font-size: 11px;
}
.empty-events {
  font-size: 12px;
  color: #91a184;
  padding: 20px 24px 30px;
}
.footer {
  padding: 26px 0 32px;
  color: #a5ae99;
  font-size: 9px;
  letter-spacing: 0.6px;
  display: flex;
  justify-content: space-between;
  gap: 15px;
}
.footer-dot {
  margin: 0 8px;
  color: #c4ccbb;
}
.notice {
  position: fixed;
  bottom: 22px;
  left: 50%;
  transform: translateX(-50%);
  width: max-content;
  max-width: calc(100vw - 32px);
  background: #264d3e;
  color: #f4f6e7;
  padding: 13px 20px;
  border: 1px solid #62785b;
  border-radius: 8px;
  font-size: 12px;
  box-shadow: 0 6px 25px #10251a28;
  z-index: 10;
  line-height: 1.7;
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
@media (min-width: 1550px) {
  .world-grid {
    max-height: 610px;
  }
}
@media (max-width: 1050px) {
  .workspace {
    padding: 28px 24px 0;
  }
  .topbar {
    padding: 0 24px;
  }
  .main-layout {
    grid-template-columns: minmax(0, 1fr) 285px;
    gap: 16px;
  }
  .edition {
    display: none;
  }
  .session-actions {
    gap: 10px;
  }
  .rule-badge {
    display: none;
  }
  .panel-heading {
    padding: 18px 18px 16px;
  }
  .map-legend {
    gap: 12px;
    padding: 12px 18px;
  }
  .map-tip {
    display: none;
  }
}
@media (max-width: 780px) {
  .topbar {
    height: 65px;
    padding: 0 18px;
  }
  .brand {
    font-size: 9px;
    letter-spacing: 0.8px;
  }
  .brand-symbol {
    width: 27px;
    height: 27px;
    font-size: 22px;
  }
  .header-actions {
    gap: 0;
  }
  .header-actions .button {
    font-size: 10px;
    padding: 9px 6px;
  }
  .workspace {
    padding: 24px 16px 0;
  }
  .main-layout {
    grid-template-columns: 1fr;
  }
  .inspector {
    grid-template-columns: 1fr 1fr;
    align-items: start;
    gap: 16px;
  }
  .page-heading {
    margin-bottom: 24px;
  }
  .page-heading .eyebrow {
    font-size: 8px;
    letter-spacing: 1px;
  }
  h1 {
    font-size: 28px;
  }
  .subtitle {
    font-size: 11px;
  }
  .agent-token {
    font-size: 12px;
  }
  .panel-heading {
    padding: 18px;
  }
  .rule-badge {
    display: none;
  }
  .footer {
    flex-wrap: wrap;
  }
