        state: 'solid',
      },
      data: {},
      createdBy: null,
      createdAt: 0,
      revision: 'fixture',
    });
    expect(
      v7Route(
        world,
        present(world.actors[0]),
        { x: 4.4, y: 2 },
        v7Work(2_000_000),
      ),
    ).toEqual([{ x: 4.4, y: 2 }]);
    const failed = step(world, {
      interface: 'navigate',
      args: { target: 'wall', x: 0, y: 0 },
    });
